let evidenceFilter='all',registrationFilter='all';
function evidencePage(){return `<section class="page-intro"><span class="eyebrow">CLINICAL EVIDENCE</span><h1>Research you can examine.</h1><p>Four supplied publications, with their findings and limits. Assessment evidence is kept separate from home rehabilitation claims.</p></section><div class="container section"><div class="filter-bar" aria-label="Filter research">${[['all','All publications · 4'],['vr','VR assessment · 2'],['related','Related assessment · 2']].map(([k,t])=>`<button class="filter ${evidenceFilter===k?'selected':''}" data-study-filter="${k}" aria-pressed="${evidenceFilter===k}">${t}</button>`).join('')}</div><div class="study-grid">${studies.filter(s=>evidenceFilter==='all'||s.group===evidenceFilter).map(s=>`<article class="study-card" data-study-group="${s.group}"><div class="study-meta">${s.group==='vr'?'VR EYE-TRACKING ASSESSMENT':'RELATED ASSESSMENT RESEARCH'}</div><small>${s.journal}</small><h3>${s.title}</h3><p class="fine">${s.authors}</p><div class="study-result"><b>${s.n}</b><span>${s.result}</span></div><p>${s.summary}</p><details><summary>Applicability & limitations</summary><p><b>Scope:</b> ${s.scope}</p><p><b>Limitations:</b> ${s.limit}</p></details><div class="buttons"><a class="text-link" href="https://doi.org/${s.doi}" target="_blank" rel="noopener">Publisher article</a><a class="text-link" href="/documents/${s.file}.pdf" target="_blank" rel="noopener">Supplied PDF</a></div></article>`).join('')}</div><div class="notice">These studies investigate assessment or screening. They do not establish the treatment efficacy, prevention benefit or regulatory status of the proposed QuickMind Home Plan.</div><div class="buttons"><a class="btn outline" href="/pages/registrations/" data-route>Explore Registration Documents</a><a class="text-link" href="/home-product/" data-route>Return to Home Product</a></div></div>`}
function registrationPage(){return `<section class="page-intro"><span class="eyebrow">GLOBAL DOCUMENTATION</span><h1>Product scope.<br>Market-specific records.</h1><p>Review the supplied registration, listing and conformity documents. Each record is tied to its named product and jurisdiction.</p></section><div class="container section"><div class="filter-bar" aria-label="Filter registration documents">${[['all','All product families'],['cognitive','Cognitive / Virtual Brain'],['other','Attention & ASD']].map(([k,t])=>`<button class="filter ${registrationFilter===k?'selected':''}" data-registration-filter="${k}" aria-pressed="${registrationFilter===k}">${t}</button>`).join('')}</div><div class="registration-grid">${registrations.filter(r=>registrationFilter==='all'||r.group===registrationFilter).map(r=>`<article class="registration-card" data-registration-group="${r.group}"><div class="registration-region">${r.region}</div><span class="study-meta">${r.type}</span><h3>${r.product}</h3><p class="registration-number">${r.number}</p><p class="fine">${r.issuer}<br>${r.dates}</p><p>${r.scope}</p><details><summary>Document status & scope</summary><p>${r.status}</p></details><div class="buttons"><a class="text-link" href="/documents/${r.file}.pdf" target="_blank" rel="noopener">View Original Document</a>${r.extra?`<a class="text-link" href="/documents/${r.extra}.pdf" target="_blank" rel="noopener">Third-party record</a>`:''}</div></article>`).join('')}</div><div class="notice">Document review is based on the files supplied on 4 October 2026, not a live authority-status check. Registration, listing, notification and conformity certification are different records. They do not establish worldwide shipping eligibility or apply automatically to every commercial SKU.</div><p class="fine">FDA registration and listing do not denote approval, clearance or authorization. <a class="text-link" href="https://www.fda.gov/medical-devices/consumers-medical-devices/are-there-fda-registered-or-fda-certified-medical-devices-how-do-i-know-what-fda-approved" target="_blank" rel="noopener">FDA explanation</a></p></div>`}
document.addEventListener('click',e=>{const s=e.target.closest('[data-study-filter]');if(s){evidenceFilter=s.dataset.studyFilter;render(false)}const r=e.target.closest('[data-registration-filter]');if(r){registrationFilter=r.dataset.registrationFilter;render(false)}});
